"""Add two individual polis accounts after deepen-history.py; never invent their polygons."""
import pathlib,json
root=pathlib.Path(__file__).resolve().parents[1];p=root/'dist/data/relation-atlas.json';a=json.load(open(p));d=root/'dist/locales/en.json';en=json.load(open(d))
def T(s):ru,english=s.split('||');en[ru]=english;return ru
source='auth-greek-museum';a['sources'][source]={'title':T('Национальный археологический музей Греции · классический период||National Archaeological Museum of Greece · Classical period'),'url':'https://www.namuseum.gr/en/collection/klasiki-periodos/'}
for id,name,start,end,coords,government,society,economy,summary,belief,aliases in [
('auth-athens','Афины · классический полис||Athens · Classical polis',-508,-322,[23.7275,37.9838],'Гражданские собрания, совет и магистраты; участие ограничено гражданским статусом.||Citizen assemblies, a council and magistrates; participation was restricted by citizenship.','Граждане, метеки и порабощённые люди имели разные права; женщины были исключены из народного собрания.||Citizens, resident foreigners and enslaved people had different rights; women were excluded from the assembly.','Морская торговля, ремесло, земледелие Аттики и серебряные рудники Лавриона.||Maritime trade, crafts, Attic agriculture and the silver mines of Laurion.','Афины были самостоятельным городом-государством Аттики. Они возглавили Делосский союз, соперничали со Спартой и неоднократно меняли своё политическое устройство.||Athens was an independent city-state in Attica. It led the Delian League, rivalled Sparta and repeatedly changed its political institutions.','Культ Афины, праздники Диониса и общественные святилища соединяли религию с жизнью гражданской общины.||The cult of Athena, festivals of Dionysus and public sanctuaries joined religion to civic life.',['Athens','Classical Athens','Афины']),
('auth-sparta','Спарта · лакедемонская община||Sparta · Lacedaemonian community',-650,-192,[22.43,37.075],'Два царя, герусия, эфоры и собрание граждан; разные институты ограничивали друг друга.||Two kings, a council of elders, ephors and a citizen assembly; different institutions constrained one another.','Спартиаты, периэки и зависимые илоты занимали принципиально разные социальные позиции.||Spartiates, perioikoi and dependent helots occupied fundamentally different social positions.','Земледелие Лаконии и Мессении, труд илотов и участие в пелопоннесских политических сетях.||Agriculture in Laconia and Messenia, helot labour and participation in Peloponnesian political networks.','Спарта была конкретным полисом Пелопоннеса, а не названием всей древней Греции. Её военная и общественная организация отличалась от афинской, а власть за пределами Лаконии менялась.||Sparta was a particular Peloponnesian polis, not the name of ancient Greece as a whole. Its military and social organization differed from Athens, and its power beyond Laconia changed.','Святилища Артемиды Орфии и Аполлона, праздники и гражданские обряды составляли часть местной религиозной жизни.||Sanctuaries of Artemis Orthia and Apollo, festivals and civic rites formed part of local religious life.',['Sparta','Lacedaemon','Спарта','Лакедемон'])]:
 c={'id':id,'name':T(name),'start':start,'end':end,'coordinates':coords,'region':'Европа','kind':T('Город-государство||City-state'),'government':T(government),'society':T(society),'economy':T(economy),'summary':T(summary),'beliefSummary':T(belief),'religions':['classical'],'sources':[source],'rulers':[],'events':[],'aliases':T(' '.join(aliases)+'||'+' '.join(x for x in aliases if not any('А'<=c<='я' for c in x))),'areaNames':aliases,'approximate':True,'note':T('Даты ограничивают рассматриваемый политический период, а не всё время существования поселения. Точка обозначает город; отдельные границы не реконструированы.||Dates delimit the political period discussed, not the settlement’s entire existence. The point marks the city; separate boundaries have not been reconstructed.')}
 for alias in aliases:
  if any('А'<=x<='я' for x in alias):en[alias]='Athens' if id=='auth-athens' else 'Lacedaemon' if alias=='Лакедемон' else 'Sparta'
 a['cultures']=[x for x in a['cultures'] if x['id']!=id]+[c]
p.write_text(json.dumps(a,ensure_ascii=False,indent=1)+'\n');d.write_text(json.dumps(en,ensure_ascii=False,indent=1)+'\n')
